#include "dozi/core/MasteringProcessorChain.h"
#include "dozi/core/MasteringDsp.h"
#include <algorithm>
#include <cmath>
#include <numbers>
#include <stdexcept>

namespace dozi::core { namespace {
double get(const MasteringModulePlan&m,const char*k,double fallback){const auto i=m.parameters.find(k);return i==m.parameters.end()?fallback:i->second;}
double levelDb(double value){return value<=1e-12?-120.0:20*std::log10(value);}
ProcessorTelemetry measure(MasteringModuleType type,const StereoAudioBuffer&input,const StereoAudioBuffer&output){ProcessorTelemetry result;result.type=type;double inputPeak=0,outputPeak=0,inputPower=0,outputPower=0,lr=0,ll=0,rr=0;const auto frames=std::min(input.left.size(),output.left.size());for(std::size_t i=0;i<frames;++i){inputPeak=std::max({inputPeak,std::abs(input.left[i]),std::abs(input.right[i])});outputPeak=std::max({outputPeak,std::abs(output.left[i]),std::abs(output.right[i])});inputPower+=input.left[i]*input.left[i]+input.right[i]*input.right[i];outputPower+=output.left[i]*output.left[i]+output.right[i]*output.right[i];lr+=output.left[i]*output.right[i];ll+=output.left[i]*output.left[i];rr+=output.right[i]*output.right[i];if(std::max(std::abs(input.left[i]),std::abs(input.right[i]))>=.999)++result.peakEventCount;}result.inputPeakDbfs=levelDb(inputPeak);result.outputPeakDbfs=levelDb(outputPeak);result.inputRmsDbfs=levelDb(std::sqrt(inputPower/std::max<std::size_t>(1,frames*2)));result.outputRmsDbfs=levelDb(std::sqrt(outputPower/std::max<std::size_t>(1,frames*2)));result.maximumGainReductionDb=std::max(0.0,result.inputPeakDbfs-result.outputPeakDbfs);result.phaseCorrelation=ll>0&&rr>0?std::clamp(lr/std::sqrt(ll*rr),-1.0,1.0):1.0;if(frames){const auto stride=std::max<std::size_t>(1,frames/128);for(std::size_t i=0;i<frames&&result.vectorscope.size()<128;i+=stride)result.vectorscope.push_back({output.left[i],output.right[i]});}return result;}
}
void MasteringProcessorChain::setPlan(MasteringPlan value){currentPlan=std::move(value);}
void MasteringProcessorChain::reset(){broadbandCompressor.reset();stereoProcessor.reset();}
std::vector<ProcessorTelemetry> MasteringProcessorChain::process(StereoAudioBuffer&audio,bool auditionMode,ProcessorTelemetryCallback callback){std::vector<ProcessorTelemetry> telemetry;for(const auto&m:currentPlan.modules){const auto input=audio;if(m.type==MasteringModuleType::linearPhaseEq){LinearPhaseEqSettings s;s.bypassed=m.bypassed;for(int n=1;;++n){const auto p="band"+std::to_string(n)+".";if(!m.parameters.contains(p+"frequencyHz"))break;s.bands.push_back({get(m,(p+"frequencyHz").c_str(),1000),get(m,(p+"gainDb").c_str(),0),get(m,(p+"q").c_str(),4)});}if(m.parameters.contains("assistantLowEnd.frequencyHz"))s.bands.push_back({get(m,"assistantLowEnd.frequencyHz",80),get(m,"assistantLowEnd.gainDb",0),get(m,"assistantLowEnd.q",.7)});LinearPhaseEq{}.process(audio,s);}
else if(m.type==MasteringModuleType::dynamicEq){DynamicEqSettings s;s.bypassed=m.bypassed;for(int n=1;;++n){const auto p="band"+std::to_string(n)+".";if(!m.parameters.contains(p+"frequencyHz"))break;const auto gain=get(m,(p+"gainDb").c_str(),0);if(gain<0)s.bands.push_back({get(m,(p+"frequencyHz").c_str(),3000),get(m,(p+"q").c_str(),1),get(m,(p+"thresholdDbfs").c_str(),-30),std::abs(gain),get(m,(p+"attackMs").c_str(),10),get(m,(p+"releaseMs").c_str(),120),get(m,(p+"enabled").c_str(),1)>.5,auditionMode&&get(m,(p+"listen").c_str(),0)>.5});}DynamicEqualizer{}.process(audio,s);}
else if(m.type==MasteringModuleType::deEsser)DeEsser{}.process(audio,{m.bypassed,get(m,"frequencyHz",6500),get(m,"q",1),get(m,"thresholdDbfs",-30),get(m,"ratio",3),get(m,"maximumReductionDb",6),get(m,"attackMs",2),get(m,"releaseMs",80),auditionMode&&get(m,"listen",0)>.5});
else if(m.type==MasteringModuleType::broadbandCompressor)broadbandCompressor.process(audio,{m.bypassed,get(m,"thresholdDbfs",-18),get(m,"ratio",1.5),get(m,"attackMs",30),get(m,"releaseMs",150),get(m,"makeupGainDb",0),get(m,"sidechainHpfHz",0),get(m,"automaticRelease",0)>.5,get(m,"autoMakeup",0)>.5});
else if(m.type==MasteringModuleType::multibandCompressor){const auto ratio=get(m,"ratio",1.5),maximum=get(m,"maximumGainReductionDb",3);const auto band=[&](const char*name,double threshold,double attack,double release){const auto p=std::string(name)+".";return MultibandCompressorBandSettings{get(m,(p+"thresholdDbfs").c_str(),threshold),get(m,(p+"ratio").c_str(),ratio),get(m,(p+"attackMs").c_str(),attack),get(m,(p+"releaseMs").c_str(),release),get(m,(p+"maximumReductionDb").c_str(),maximum),auditionMode&&get(m,(p+"solo").c_str(),0)>.5};};MultibandCompressor{}.process(audio,{m.bypassed,get(m,"lowCrossoverHz",120),get(m,"midCrossoverHz",700),get(m,"highCrossoverHz",4000),band("low",-18,30,180),band("lowMid",-18,24,160),band("highMid",-19,14,120),band("high",-20,8,100)});}
else if(m.type==MasteringModuleType::saturation){const auto character=static_cast<int>(std::clamp(get(m,"character",get(m,"mode",1)),0.0,2.0));HarmonicSaturator{}.process(audio,{m.bypassed,static_cast<SaturationMode>(character),get(m,"driveDb",2),get(m,"mix",1),get(m,"outputTrimDb",0),static_cast<int>(get(m,"oversamplingFactor",4)),get(m,"automaticLevelCompensation",1)>.5,get(m,"maximumCompensationDb",3),get(m,"outputCeilingDbfs",-.1)});}
else if(m.type==MasteringModuleType::stereoWidthMonoBass)stereoProcessor.process(audio,{m.bypassed,get(m,"widthFactor",1),get(m,"monoBassCrossoverHz",120),get(m,"sideTrimDb",0),get(m,"balance",0),auditionMode&&get(m,"monoCheck",0)>.5,get(m,"swapLeftRight",0)>.5});
else if(m.type==MasteringModuleType::truePeakLimiter){const auto metrics=TruePeakLimiter{}.process(audio,{m.bypassed,get(m,"inputGainDb",0),get(m,"ceilingDbtp",-1),get(m,"lookaheadMs",5),get(m,"releaseMs",100),get(m,"linked",1)>.5,get(m,"truePeakEnabled",1)>.5});auto value=measure(m.type,input,audio);value.maximumGainReductionDb=metrics.maximumGainReductionDb;if(callback)callback(value);telemetry.push_back(std::move(value));continue;}
else if(!m.bypassed)throw std::runtime_error("Mastering plan contains an unsupported active processor");auto value=measure(m.type,input,audio);if(callback)callback(value);telemetry.push_back(std::move(value));}return telemetry;}
}
